PROCEDURE PRINT_ORG_CHART IS
  CURSOR C1 IS
    SELECT EMPLOYEE_ID, MANAGER_ID, LEVEL AS LVL
    FROM EMPLOYEES
    START WITH MANAGER_ID IS NULL
    CONNECT BY PRIOR EMPLOYEE_ID = MANAGER_ID;
BEGIN
  FOR REC IN C1 LOOP
    DBMS_OUTPUT.PUT_LINE(RPAD(' ', REC.LVL * 2) || REC.EMPLOYEE_ID);
  END LOOP;
END PRINT_ORG_CHART;
